<h2 class="h4 mb-3">生成卡密批次</h2><form method="post" class="card p-3 admin-form"><?= csrf_field() ?><div class="mb-3"><label class="form-label">批次名称</label><input class="form-control" name="name" required></div><div class="row"><div class="col-md-4 mb-3"><label class="form-label">面值</label><input class="form-control" type="number" step="0.01" name="face_value" required></div><div class="col-md-4 mb-3"><label class="form-label">数量</label><input class="form-control" type="number" name="qty" min="1" value="10" required></div><div class="col-md-4 mb-3"><label class="form-label">前缀</label><input class="form-control" name="prefix"></div><div class="col-md-4 mb-3"><label class="form-label">过期日期</label><input class="form-control" type="date" name="expire_date"></div><div class="col-md-4 mb-3"><label class="form-label">每用户上限</label><input class="form-control" type="number" name="per_user_limit" value="0"></div></div><div class="mb-3"><label class="form-label">备注</label><textarea class="form-control" name="note"></textarea></div><button class="btn btn-primary">生成</button></form>